solution.solution.cpp:
namespace my
{
    template <typename T, typename U>
    struct IsSame
    {
        static constexpr bool value{ false };
    };

    template <typename T>
    struct IsSame<T, T>
    {
        static constexpr bool value{ true };
    };

    template <typename T, typename U>
    inline constexpr bool isSame{ IsSame<T, U>::value };

    template <typename T>
    struct RemoveConst
    {
        using type = T;
    };

    template <typename T>
    struct RemoveConst<const T>
    {
        using type = T;
    };

    template <typename T>
    using RemoveConst_t = typename RemoveConst<T>::type;
}

unitTests:
static_assert(my::IsSame<int, int>::value && !my::IsSame<int, long>::value && !my::IsSame<int, const int>::value);
static_assert(my::isSame<double, double> && !my::isSame<double, float>);
static_assert(std::is_same_v<my::RemoveConst<const int>::type, int>);
static_assert(std::is_same_v<my::RemoveConst_t<int>, int>);
static_assert(std::is_same_v<my::RemoveConst_t<const std::string>, std::string>);
static_assert(std::is_same_v<my::RemoveConst_t<const int*>, const int*>, "the const here belongs to the int being pointed at, not to the pointer");

TEST("the traits also give values at run time") { CHECK(my::isSame<char, char>); CHECK(!my::isSame<char, bool>); }

